import{_ as t,o as e,c as i,a3 as l}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"LocalAI のインストール","description":"LocalAI で OpenAI 互換 API を提供。Docker またはバイナリ導入後に MiniTavern へ接続。","frontmatter":{"title":"LocalAI のインストール","description":"LocalAI で OpenAI 互換 API を提供。Docker またはバイナリ導入後に MiniTavern へ接続。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"LocalAI のインストール · MiniTavern Docs"}],["meta",{"property":"og:description","content":"LocalAI で OpenAI 互換 API を提供。Docker またはバイナリ導入後に MiniTavern へ接続。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/localai/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/localai/install"}]]},"headers":[],"relativePath":"ja/localai/install.md","filePath":"ja/localai/install.md","lastUpdated":1787224147000}'),n={name:"ja/localai/install.md"};function r(o,a,s,d,c,h){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="インストールと接続-localai" tabindex="-1">インストールと接続（LocalAI） <a class="header-anchor" href="#インストールと接続-localai" aria-label="Permalink to &quot;インストールと接続（LocalAI）&quot;">​</a></h1><p><a href="https://localai.io/" target="_blank" rel="noreferrer">LocalAI</a> はローカルの OpenAI 互換 API ゲートウェイで、複数バックエンドにつなげます。Docker に慣れている、または「一つの互換層で複数モデル」したい人向け。</p><h2 id="クイック起動-docker-例" tabindex="-1">クイック起動（Docker 例） <a class="header-anchor" href="#クイック起動-docker-例" aria-label="Permalink to &quot;クイック起動（Docker 例）&quot;">​</a></h2><p>イメージ名とポートは <a href="https://localai.io/" target="_blank" rel="noreferrer">公式ドキュメント</a> 準拠、示意：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8080:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local-ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localai/localai:latest</span></span></code></pre></div><p>初回はドキュメントどおりモデルを配置または pull；本機でアクセスできることを確認：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:8080/v1/models</span></span></code></pre></div><h2 id="lan" tabindex="-1">LAN <a class="header-anchor" href="#lan" aria-label="Permalink to &quot;LAN&quot;">​</a></h2><ul><li>コンテナポートをホストへマップ後、ファイアウォールで <strong>8080</strong>（またはマップしたポート）を開放。</li><li>スマホ：<code>http://YOUR_PC_IP:8080/v1</code>。</li><li>コンテナが誤った NIC だけにバインドしている場合は、Docker のポート公開とホストファイアウォールを確認。</li></ul><h2 id="minitavern-向け" tabindex="-1">MiniTavern 向け <a class="header-anchor" href="#minitavern-向け" aria-label="Permalink to &quot;MiniTavern 向け&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>記入</th></tr></thead><tbody><tr><td>モデルプラットフォーム</td><td>カスタム（OpenAI 互換）</td></tr><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:8080/v1</code></td></tr><tr><td>API Key</td><td>LocalAI の認証有無に従う</td></tr><tr><td>モデル名</td><td>LocalAI 設定の model id と一致</td></tr></tbody></table><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><p><a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern での設定</a> · <a href="/ultra_guides/ja/local/tools">ツール一覧</a> · <a href="/ultra_guides/ja/troubleshoot">排錯</a></p>',13)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
